  "Put the pot on the largest burner, turn it to HIGH and put the lid on (it boils faster).": "ქვაბი დადგით ყველაზე დიდ კონფორკაზე, ჩართეთ ᲫᲚᲘᲔᲠ ცეცხლზე და დაახურეთ სახურავი (ასე უფრო სწრაფად ადუღდება).",
