  "Bottom scraped clean": "ძირი სუფთად არის გაფხეკილი",
  "Let it cook": "მოხარშვა",
  "Let it bubble for a couple of minutes.": "ადუღეთ რამდენიმე წუთის განმავლობაში.",
  "Beer mostly evaporated": "ლუდის უმეტესი ნაწილი აორთქლდა",
  "Tomato paste": "ტომატის პასტა",
  "Add the tomato paste and fry it for 1 minute, stirring.": "დაამატეთ ტომატის პასტა და შეწვით 1 წუთი, მორევით.",
  "Darker, fragrant": "უფრო მუქია, სურნელოვანი",
  "Tomatoes in": "პომიდორი შიგნით",
  "Add the chopped tomatoes and keep stirring.": "დაამატეთ დაჭრილი პომიდორი და განაგრძეთ მორევა.",
  "Mixed in": "არეულია",
  "Chocolate, oregano, liquid": "შოკოლადი, ორეგანო, სითხე",
  "Add the dark chocolate chunks, the oregano and the stock (or water). Stir.": "დაამატეთ მუქი შოკოლადის ნაჭრები, ორეგანო და ბულიონი (ან წყალი). მოურიეთ.",
  "Chocolate melted in": "შოკოლადი გადნა",
  "Bring to a boil": "ადუღება",
  "Let it come to a boil.": "ადუღეთ.",
  "Bubbling all over": "მთელ ზედაპირზე ბუყბუყებს",
  "Simmer, covered": "ნელ ცეცხლზე, დახურული",
  "Turn the heat down, cover and simmer. Stir every 10 minutes.": "შეამცირეთ ცეცხლი, დაახურეთ და ნელ ცეცხლზე ადუღეთ. მოურიეთ ყოველ 10 წუთში.",
  "# min passed": "# წუთი გავიდა",
