  "Finish simmering": "ნელ ცეცხლზე დასრულება",
  "Simmer for the last stretch. Take the lid off if it needs thickening. Stir every 10 minutes.": "ბოლო მონაკვეთი ნელ ცეცხლზე ადუღეთ. თუ გასქელება სჭირდება, მოხადეთ სახურავი. მოურიეთ ყოველ 10 წუთში.",
