  "Lightly charred spots": "ოდნავ დამწვარი ლაქები",
  "Ladle into bowls. Top with grated cheddar, a spoon of sour cream and a few cilantro leaves. Tortillas (or rice) on the side, lime wedge optional.": "ჩამჩით ჩაასხით ჯამებში. ზემოდან დაადეთ გახეხილი ჩედერი, ერთი კოვზი არაჟანი და ქინძის რამდენიმე ფოთოლი. გვერდზე ტორტილები (ან ბრინჯი), სურვილისამებრ ლაიმის ნაჭერი.",
  "Dice the onion … Chop the tomatoes": "ხახვის დაჭრა … პომიდვრის დაჭრა",
