  "Cook the rice": "ბრინჯის მოხარშვა",
  "Wash the rice until the water runs clear. Cook it in 1.5× its volume of lightly salted water; when the water level meets the rice, cover on the lowest heat for 10 to 12 min, then rest covered 10 to 15 min.": "ბრინჯი რეცხეთ, სანამ წყალი არ გამჭვირვალდება. მოხარშეთ მისი მოცულობის 1,5×-ის ოდენობის ოდნავ დამარილებულ წყალში; როცა წყლის დონე ბრინჯს გაუსწორდება, დაახურეთ ყველაზე სუსტ ცეცხლზე 10-დან 12 წუთამდე, შემდეგ დახურული დაასვენეთ 10-დან 15 წუთამდე.",
  "Fluffy, water absorbed": "ფხვიერია, წყალი შეიწოვა",
  "Grate the cheddar · Serve": "ჩედერის გახეხვა · მიტანა",
