  "Spices in the milk": "სანელებლები რძეშია",
  "Portion semolina and sugar": "მანის ბურღულისა და შაქრის გაზომვა",
  "Measure the semolina and the sugar (or erythritol). Per 1 dl milk: 1 tbsp semolina, ½ tbsp sugar (or ⅔ tbsp erythritol).": "გაზომეთ მანის ბურღული და შაქარი (ან ერითრიტოლი). 1 დლ რძეზე: 1 ს.კ. მანის ბურღული, ½ ს.კ. შაქარი (ან ⅔ ს.კ. ერითრიტოლი).",
  "Both measured": "ორივე გაზომილია",
  "Heat until steaming": "გაცხელება ორთქლამდე",
