  "No lumps": "უსიმსივნოდ",
  "Cook on low": "სუსტ ცეცხლზე მოხარშვა",
  "Keep stirring on low heat.": "განაგრძეთ მორევა სუსტ ცეცხლზე.",
  "Thick and smooth": "სქელი და ერთგვაროვანი",
  "Heat off, rosewater": "ცეცხლი გამორთული, ვარდის წყალი",
  "Turn off the heat. Add a little rosewater near the end and keep stirring.": "გამორთეთ ცეცხლი. ბოლოს დაამატეთ ცოტა ვარდის წყალი და განაგრძეთ მორევა.",
  "Rosewater stirred in": "ვარდის წყალი შერეულია",
  "Plate while hot": "ცხლად თეფშზე გადაღება",
  "While it is still hot and runny, pour it onto flat plates. Once it cools in the pot it sets and won't spread.": "სანამ ჯერ კიდევ ცხელი და თხიერია, ჩაასხით ბრტყელ თეფშებზე. ქვაბში გაციების შემდეგ მაგრდება და აღარ გაიშლება.",
  "Spread on the plates": "თეფშებზე გაშლილია",
  "Dust and serve": "მოყრა და მირთმევა",
  "Just before serving, sprinkle cocoa powder (and cinnamon) on top.": "მირთმევის წინ ზემოდან მოაყარეთ კაკაოს ფხვნილი (და დარიჩინი).",
  "Dusted": "მოყრილია",
  "Milk on the stove … Heat off, rosewater": "რძე ქურაზე … ცეცხლი გამორთული, ვარდის წყალი",
