  "Plate while hot · Dust and serve": "ცხლად თეფშზე გადაღება · მოყრა და მირთმევა",
  "Dice the chicken": "ქათმის კუბიკებად დაჭრა",
  "Cut the chicken breast into small 2 to 3 cm chunks.": "ქათმის მკერდი დაჭერით 2-დან 3 სმ-მდე პატარა ნაჭრებად.",
  "Even chunks": "თანაბარი ნაჭრები",
  "Grate the garlic": "ნივრის გახეხვა",
