  "Mix the marinade": "მარინადის მომზადება",
  "In a container, add the chicken with the oil, gochujang, light soy sauce, salt, MSG, white pepper, sugar or honey, garlic and sesame oil. Mix well and cover.": "ჭურჭელში ჩადეთ ქათამი ზეთთან, გოჩუჯანგთან, ღია სოიოს სოუსთან, მარილთან, MSG-სთან, თეთრ პილპილთან, შაქართან ან თაფლთან, ნიორთან და სეზამის ზეთთან ერთად. კარგად აურიეთ და დაახურეთ.",
