  "Marinate in the fridge": "მარინირება მაცივარში",
  "Leave it covered in the fridge.": "დახურული დატოვეთ მაცივარში.",
  "At least 30 min passed": "გავიდა მინიმუმ 30 წუთი",
  "Measure rice and water": "ბრინჯისა და წყლის გაზომვა",
  "Measure the rice in cups. In a bowl, mix 1.5× its volume of water with the salt.": "ბრინჯი გაზომეთ ჭიქებით. ჯამში მისი მოცულობის 1,5×-ის ოდენობის წყალი აურიეთ მარილთან.",
  "Measured": "გაზომილია",
  "Wash the rice": "ბრინჯის გარეცხვა",
  "Wash the rice in lukewarm water in a sieve, stirring slowly, until the water runs clear. Let it drain a little.": "ბრინჯი საცერში რეცხეთ თბილ წყალში, ნელა მორევით, სანამ წყალი არ გამჭვირვალდება. ცოტა ხნით დატოვეთ, რომ ჩაიწუროს.",
  "Water runs clear": "წყალი გამჭვირვალეა",
  "Toast the rice": "ბრინჯის მოხალვა",
  "Heat the oil in a pan and toast the rice, stirring slowly, until it smells fragrant. Don't really fry it.": "ტაფაში გააცხელეთ ზეთი და მოხალეთ ბრინჯი, ნელა მორევით, სანამ სურნელს არ გამოსცემს. ნამდვილად ნუ შეწვავთ.",
  "Water in": "წყალი შიგნით",
  "Add the salted water and stir once, very slowly.": "დაამატეთ მარილიანი წყალი და ერთხელ, ძალიან ნელა მოურიეთ.",
  "Boil down": "ადუღება",
  "Let it boil until the water level roughly matches the rice level.": "ადუღეთ, სანამ წყლის დონე დაახლოებით ბრინჯის დონეს არ გაუთანაბრდება.",
  "Water level at the rice": "წყლის დონე ბრინჯის დონეზეა",
  "Cover, lowest heat": "დახურვა, ყველაზე სუსტი ცეცხლი",
  "Set the lowest heat and cover. Don't stir or lift the lid.": "დააყენეთ ყველაზე სუსტი ცეცხლი და დაახურეთ. არ მოურიოთ და სახურავი არ ახადოთ.",
  "Time is up": "დრო ამოიწურა",
  "Rest, covered": "დასვენება, დახურული",
  "Take it off the heat, keep the lid on.": "გადმოდგით ცეცხლიდან, სახურავი არ მოხადოთ.",
  "Rested": "დაისვენა",
  "Julienne the vegetables": "ბოსტნეულის ჩალისებრად დაჭრა",
