  "Matchstick-sized": "ასანთის ღერის ზომის",
  "Prepare the bok choy": "ბოკ ჩოის მომზადება",
  "Tear the bok choy apart by leaves and wash it thoroughly.": "ბოკ ჩოი ფოთლებად დაშალეთ და კარგად გარეცხეთ.",
  "Clean leaves": "სუფთა ფოთლები",
  "Mix the sauce": "სოუსის მომზადება",
  "Mix the gochujang, sesame oil, sugar or honey, rice vinegar, water, sesame seeds and grated garlic.": "აურიეთ გოჩუჯანგი, სეზამის ზეთი, შაქარი ან თაფლი, ბრინჯის ძმარი, წყალი, სეზამის მარცვლები და გახეხილი ნიორი.",
  "Smooth sauce": "ერთგვაროვანი სოუსი",
  "Chicken into the pan": "ქათამი ტაფაში",
  "Heat a large pan on medium-high with a little oil. Add the marinated chicken.": "დიდი ტაფა გააცხელეთ საშუალოზე ძლიერ ცეცხლზე ცოტა ზეთით. დაამატეთ მარინირებული ქათამი.",
  "Chicken spread out": "ქათამი გაშლილია",
  "Stir-fry the chicken": "ქათმის სწრაფად შეწვა",
  "Stir-fry until done.": "შეწვით მორევით, სანამ არ მზადდება.",
  "No pink inside": "შიგნით ვარდისფერი აღარ არის",
  "Chicken out": "ქათამი გარეთ",
  "Take the chicken out of the pan.": "ქათამი ამოიღეთ ტაფიდან.",
  "Chicken set aside": "ქათამი გვერდზეა გადადებული",
  "Water and oil in the pan": "წყალი და ზეთი ტაფაში",
  "Clean the pan (or use another). While cold, add a few tbsp of water and a few tsp of oil, then heat it.": "გაწმინდეთ ტაფა (ან აიღეთ სხვა). სანამ ცივია, დაამატეთ რამდენიმე ს.კ. წყალი და რამდენიმე ჩ.კ. ზეთი, შემდეგ გააცხელეთ.",
  "Hot and steaming": "ცხელია და ორთქლდება",
  "Steam-fry the bok choy": "ბოკ ჩოის ორთქლზე შეწვა",
  "Add the bok choy with a little salt, stirring. Don't overcook it.": "დაამატეთ ბოკ ჩოი ცოტა მარილით, მორევით. ზედმეტად არ მოხარშოთ.",
  "Just wilted, still green": "ახლახან დაჭკნა, ჯერ კიდევ მწვანეა",
  "Fry the eggs": "კვერცხების შეწვა",
  "Fry the eggs sunny side up in a small pan with a little oil, one at a time. Keep the yolk a little runny, salt a tiny bit, add a splash of sesame oil near the end.": "კვერცხები შეწვით თვალისებრად პატარა ტაფაში ცოტა ზეთით, სათითაოდ. გული ოდნავ თხიერი დატოვეთ, ცოტა მოამარილეთ, ბოლოს დაამატეთ სეზამის ზეთის რამდენიმე წვეთი.",
  "White set, yolk runny": "ცილა შედედდა, გული თხიერია",
  "Plate it": "თეფშზე დალაგება",
  "Rice first, the chicken next to it, the bok choy next to it, then the vegetables and the egg on top. Drizzle light soy sauce, add the green onion greens, 1 tsp of sauce and the sesame seeds.": "ჯერ ბრინჯი, გვერდით ქათამი, მის გვერდით ბოკ ჩოი, შემდეგ ზემოდან ბოსტნეული და კვერცხი. მოასხით ღია სოიოს სოუსი, დაამატეთ მწვანე ხახვის მწვანე ნაწილი, 1 ჩ.კ. სოუსი და სეზამის მარცვლები.",
  "Toast the rice … Rest, covered": "ბრინჯის მოხალვა … დასვენება, დახურული",
