  "Add the chicken to a container with a little oil, salt, mustard, honey, tarragon, the white wine (or stock + lemon juice), black pepper and a very small amount of MSG. Mix well and cover.": "ჭურჭელში ჩადეთ ქათამი ცოტა ზეთთან, მარილთან, მდოგვთან, თაფლთან, ტარხუნასთან, თეთრ ღვინოსთან (ან ბულიონი + ლიმონის წვენი), შავ პილპილთან და ძალიან მცირე რაოდენობის MSG-სთან ერთად. კარგად აურიეთ და დაახურეთ.",
