  "All cups filled": "ყველა უჯრა შევსებულია",
  "Bake": "გამოცხობა",
  "Bake until the top is slightly browned and the center is set and doesn't wobble. Whole egg with runny yolk: start checking at 12 to 14 min.": "გამოაცხვეთ, სანამ ზედა ნაწილი ოდნავ არ შეიბრაწება, შუა კი არ გამაგრდება და აღარ ირხევა. მთლიანი კვერცხი თხიერი გულით: შემოწმება დაიწყეთ 12-დან 14 წუთამდე.",
