  "Brown the chicken": "შეწვით ქათამი",
  "Heat the oil in a deep pan with a lid and brown the chicken, skin side down first, until golden on both sides. Take it out.": "გააცხელეთ ზეთი სახურავიან ღრმა ტაფაში და შეწვით ქათამი, ჯერ კანით ქვემოთ, სანამ ორივე მხრიდან ოქროსფერი არ გახდება. ამოიღეთ.",
  "Fry the onion and pepper in the chicken fat until soft, adding the garlic for the last minute.": "მოშუშეთ ხახვი და წიწაკა ქათმის ცხიმში, სანამ არ დარბილდება, ბოლო წუთზე დაამატეთ ნიორი.",
  "Coat the rice": "მოშუშეთ ბრინჯი",
  "Stir in the passata and the turmeric (or crushed saffron), then the rice, and stir for 2 minutes until coated.": "შეურიეთ პასატა და ქურქუმა (ან დაფშვნილი ზაფრანა), შემდეგ ბრინჯი, და ურიეთ 2 წუთი, სანამ ბრინჯი არ დაიფარება.",
  "Rice coated and glossy": "ბრინჯი დაფარულია და ბზინავს",
  "Simmer covered": "ჩაშუშეთ თავდახურული",
  "Pour in the stock, put the chicken back on top, bring to the boil, then cover and cook on low without stirring.": "ჩაასხით ბულიონი, ქათამი ისევ ზემოთ დადეთ, აადუღეთ, დახურეთ და დაბალ ცეცხლზე ხარშეთ ურევის გარეშე.",
  "Most of the liquid absorbed": "სითხის უმეტესი ნაწილი შეიწოვა",
  "Peas and olives": "მწვანე ბარდა და ზეთისხილი",
  "Scatter over the peas (and the olives), cover again and cook until the rice is tender and the chicken is cooked through.": "მოაყარეთ მწვანე ბარდა (და ზეთისხილი), ისევ დახურეთ და ხარშეთ, სანამ ბრინჯი არ დარბილდება და ქათამი ბოლომდე არ შეიწვება.",
  "Rice tender, chicken cooked through": "ბრინჯი რბილია, ქათამი მზადაა",
  "Leave it covered off the heat for 5 minutes, fluff the rice and serve with cilantro.": "დატოვეთ თავდახურული ცეცხლიდან მოშორებით 5 წუთი, გააფხვიერეთ ბრინჯი და მიირთვით ქინძით.",
  "Brown the chicken … Peas and olives": "შეწვით ქათამი … მწვანე ბარდა და ზეთისხილი",
  "Red kidney beans": "წითელი ლობიო",
  "Black beans": "შავი ლობიო",
  "whole chili": "მთლიანი ჩილი",
  "chili cut open": "ჩაჭრილი ჩილი",
  "bruised": "დაჭყლეტილი",
  "whole": "მთლიანი",
  "Rinse the rice until the water runs clear. Drain and rinse the beans, crush the garlic and bruise the spring onion with the back of a knife.": "რეცხეთ ბრინჯი, სანამ წყალი არ გამჭვირვალდება. გადაწურეთ და გაავლეთ ლობიო, დაჭყლიტეთ ნიორი და დანის ბრტყელი მხარით დაჭყლიტეთ მწვანე ხახვი.",
  "Infuse the coconut milk": "არომატი მიეცით ქოქოსის რძეს",
  "Bring the coconut milk and water to a simmer with the beans, garlic, spring onion, thyme, allspice and salt. Add the whole chili (cut a slit in it for the hot version).": "ქოქოსის რძე და წყალი ლობიოსთან, ნიორთან, მწვანე ხახვთან, ბეგქონდართან, სურნელოვან პილპილთან და მარილთან ერთად მიიყვანეთ ნელ დუღილამდე. დაამატეთ მთლიანი ჩილი (უფრო ცხარე ვარიანტისთვის ჩაჭერით).",
  "Simmering, fragrant": "ნელა დუღს, სურნელოვანია",
  "Stir in the rice, bring back to the boil, then cover and cook on the lowest heat without stirring. Don't burst the chili.": "შეურიეთ ბრინჯი, ისევ აადუღეთ, დახურეთ და ყველაზე დაბალ ცეცხლზე ხარშეთ ურევის გარეშე. არ დაუშვათ, რომ ჩილი გასკდეს.",
  "Liquid absorbed, rice tender": "სითხე შეიწოვა, ბრინჯი რბილია",
  "Leave it covered off the heat for 5 minutes. Remove the chili, thyme stems and spring onion, then fluff with a fork.": "დატოვეთ თავდახურული ცეცხლიდან მოშორებით 5 წუთი. ამოიღეთ ჩილი, ბეგქონდარის ღეროები და მწვანე ხახვი და ჩანგლით გააფხვიერეთ ბრინჯი.",
  "Infuse the coconut milk · Cook the rice": "არომატი მიეცით ქოქოსის რძეს · ბრინჯის მოხარშვა",
