  "juiced": "გამოწურული",
  "Peel and thinly slice the onions.": "გაფცქვენით ხახვი და დაჭერით თხელ ნახევარრგოლებად.",
  "Thin slices": "თხელი ნახევარრგოლები",
  "Make the marinade": "მოამზადეთ მარინადი",
  "Mix the lemon juice, mustard, garlic, crumbled stock cube, pepper, salt and half the oil. Add the chicken and the onions and mix well.": "აურიეთ ლიმონის წვენი, მდოგვი, ნიორი, დაფშვნილი ბულიონის კუბიკი, პილპილი, მარილი და ზეთის ნახევარი. დაამატეთ ქათამი და ხახვი და კარგად აურიეთ.",
  "Everything coated": "ყველაფერი დაფარულია",
  "Cover and marinate in the fridge for at least 1 hour (or overnight).": "დაფარეთ და მაცივარში დაამარინადეთ მინიმუმ 1 საათი (ან მთელი ღამე).",
  "Lift the chicken out of the marinade (keep the onions and the marinade) and brown it in the rest of the oil. Take it out.": "ამოიღეთ ქათამი მარინადიდან (ხახვი და მარინადი შეინახეთ) და შეწვით დარჩენილ ზეთში. ამოიღეთ.",
  "Browned on both sides": "ორივე მხრიდან შემწვარი",
  "Cook the onions": "მოშუშეთ ხახვი",
  "Fry the onions from the marinade in the same pan until soft and golden.": "იმავე ტაფაში მოშუშეთ მარინადის ხახვი, სანამ არ დარბილდება და ოქროსფერი არ გახდება.",
  "Add the rest of the marinade, the water and the bay leaf (and the chili), put the chicken back, cover and simmer until the chicken is tender. Add the olives for the last 5 minutes.": "დაამატეთ დარჩენილი მარინადი, წყალი და დაფნის ფოთოლი (და ჩილი), დააბრუნეთ ქათამი, დახურეთ და ჩაშუშეთ, სანამ ქათამი არ დარბილდება. ზეთისხილი დაამატეთ ბოლო 5 წუთზე.",
  "Chicken tender, onions jammy": "ქათამი რბილია, ხახვი მურაბასავით",
  "Serve the chicken and onions over the rice.": "მიირთვით ქათამი და ხახვი ბრინჯზე.",
  "Brown the chicken … Simmer": "შეწვით ქათამი … ნელ ცეცხლზე ადუღება",
