  "Pound the garlic and chilies to a rough paste in a mortar (or chop them finely).": "როდინში დანაყეთ ნიორი და ჩილი უხეშ პასტად (ან წვრილად დაკეპეთ).",
  "Rough paste": "უხეში პასტა",
  "Mix the oyster sauce, both soy sauces, fish sauce, sugar and water.": "აურიეთ ხამანწკის სოუსი, ორივე სოიოს სოუსი, თევზის სოუსი, შაქარი და წყალი.",
  "Heat the oil in the wok until very hot and fry the eggs one at a time, spooning hot oil over them, until the edges are crispy and the yolk is still runny. Keep them on a plate.": "ვოკში ძლიერად გააცხელეთ ზეთი და შეწვით კვერცხები სათითაოდ, ზედ ცხელი ზეთი მოასხით, სანამ კიდეები არ გახრაშუნდება და გული ჯერ კიდევ თხევადი იქნება. გადადეთ თეფშზე.",
  "Crispy edges, runny yolk": "ხრაშუნა კიდეები, თხევადი გული",
  "Fry the garlic and chilies": "მოშუშეთ ნიორი და ჩილი",
  "Heat the oil in the wok and fry the garlic and chili paste for a few seconds until fragrant.": "ვოკში გააცხელეთ ზეთი და რამდენიმე წამი მოშუშეთ ნივრისა და ჩილის პასტა, სანამ სურნელი არ ამოვა.",
  "Fragrant, not brown": "სურნელოვანია, არ შებრაწულა",
  "Add the meat and stir-fry, breaking it up, until cooked through.": "დაამატეთ ხორცი და შეწვით ურევით და დაშლით, სანამ არ შეიწვება.",
  "Sauce and basil": "სოუსი და რეჰანი",
  "Pour in the sauce and toss until glossy, then turn off the heat and stir in the basil until it wilts.": "ჩაასხით სოუსი და ურიეთ, სანამ ყველაფერი არ აბზინდება, შემდეგ გამორთეთ ცეცხლი და შეურიეთ რეჰანი, სანამ არ ჩამოჭკნება.",
  "Glossy, basil wilted": "ბზინავს, რეჰანი ჩამოჭკნა",
